head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_CND_DTE_REQ = "검색조건 중 청구서제출일이 입력되지 않아 조회할 수 없습니다.";
scwin.MSG_CND_DTE_BIG = "검색조건 중 청구서제출 시작일이, 종료일 이후이므로 조회할 수 없습니다.";
scwin.NO_EXCEL_DATA = "해당데이터가 없습니다. 조회후 다운받으십시요.";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
scwin.fn_GetPar;
scwin.glb_MenuId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        // edt_SDate.text = cGetMinusDate2(vCurDate, 365);
        edt_SDate.setValue("19000101");
        edt_EDate.setValue(vCurDate);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        await scwin.listSync();
        /*
        glb_MenuId = InfoMenuID();
        alert( "menud id:"  + glb_MenuId + "\n" +
        	   "js_id:"	    + js_id + "\n"+
        	   "js_emp_no:" + js_emp_no + "\n"+
        	   "js_pass:"	+ js_pass + "\n"+
        	   "js_emp_nm:" + js_emp_nm + "\n"+
        	   "js_dep_cd:" + js_dep_cd + "\n"+
        	   "js_market:" + js_market
        	 );
         */
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05008.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Prelisting_OnDblClick
 * @description grd_Prelisting 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Prelisting_OnDblClick = async function(row, colid) {
    try {
        await scwin.openDtl(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05008.grd_Prelisting_OnDblClick" });
    }
};

