 * @description 「공모내역」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_OpenPubofr_onclick = async function() {
    try {
        await scwin.openPubofr(dts_listPrelisting.getRowPosition());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05008.img_OpenPubofr_onclick" });
    }
};

/**
 * @method
 * @name dts_listPrelisting_OnLoadCompleted
 * @description dts_listPrelisting 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_listPrelisting_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_listPrelisting.errorMsg) {
            await $c.win.alert(dts_listPrelisting.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
        await scwin.procCheckSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05008.dts_listPrelisting_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_listPrelisting_OnLoadError
 * @description dts_listPrelisting 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_listPrelisting_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_listPrelisting);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05008.dts_listPrelisting_OnLoadError" });
    }
};

/**
