    try {
        scwin.fn_GetPar = scwin.getParIsur;
        fn_SetPar = scwin.setParIsur;
        $c.lc.fn_PopFindIsurCdCorp();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05008.btn_IsuCdSearch_onclick" });
