 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05008.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        if (dts_listPrelisting.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF05008.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_Prelisting, {fileName: "예비심사리스트", type: "3"});
        } else {
            await $c.win.alert(scwin.NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05008.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05008.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05008.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05008.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_IsurCd_onblur
 * @description txb_IsurCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurCd_onblur = function() {
    try {
        if (txb_IsurCd.getValue() === "") {
            txb_CoNm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05008.txb_IsurCd_onblur" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (!await scwin.validate()) {
        return;
    }
    const sbmOptions = {
        id : "sbm_dts_listPrelisting",
        action : "/prelistingKosdaq.do",
        ref : "",
        target : "dts_listPrelisting=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name procCheckSync
 * @description proc Check Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procCheckSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_Proc_Check",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Proc_Check=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let vCtnt = "";
    if (dts_Proc_Check.getRowCount() > 0) {
        for (let i = 1; i <= dts_Proc_Check.getRowCount(); i++) {
            vCtnt += "\r\n";
            let vNm = "";
            if (dts_Proc_Check.getCellData(i, "EXAMPRN_NM") === "") {
                vNm += "심사자";
            }
            if (dts_Proc_Check.getCellData(i, "ACPT_COMPLT") === "" || dts_Proc_Check.getCellData(i, "ACPT_COMPLT") === "N") {
                if (vNm === "") {
                    vNm += "접수자";
                } else {
                    vNm += ",접수자";
                }
            }
            if (dts_Proc_Check.getCellData(i, "REVW_COMPLT") === "" || dts_Proc_Check.getCellData(i, "REVW_COMPLT") === "N") {
                if (vNm === "") {
                    vNm += "검토자";
                } else {
                    vNm += ",검토자";
                }
            }
            if (dts_Proc_Check.getCellData(i, "COMITE_COMPLT") === "") {
                if (vNm === "") {
                    vNm += "위원회완료자";
                } else {
                    vNm += ",위원회완료자";
                }
            }
            vCtnt += "상장완료후 " + dts_Proc_Check.getCellData(i, "COM_NM") + "가 " + vNm + "가 입력이 누락되었습니다, 입력해 주시기 바랍니다.";
            vCtnt += "\r\n";
        }
        await $c.win.alert(vCtnt);
    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function() {
    if ((edt_SDate.getValue() === "") || (edt_EDate.getValue() === "")) {
        await $c.win.alert(scwin.MSG_CND_DTE_REQ);
        return;
    }
    if (edt_SDate.getValue() > edt_EDate.getValue()) {
        await $c.win.alert(scwin.MSG_CND_DTE_BIG);
        return;
    }
    return true;
};

/**
 * @method
 * @name getParIsur
 * @description 발행기관목록
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션, 발행기관 목록팝업
    arrPar[0] = txb_IsurCd; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_CoNm; // 명칭값을 포함할 컨트롤
    arrPar[2] = "KSQ_EXEM"; // 코스닥예비심사

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    txb_IsurCd.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_CoNm.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};

/**
 * @method
 * @name getParDtl
 * @description 상세화면
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParDtl = function(arrPar) {
    // 상세화면열기
    const cRow = dts_listPrelisting.getRowPosition();
    arrPar[0] = dts_listPrelisting.getCellData(cRow, "ISUR_CD");
    arrPar[1] = dts_listPrelisting.getCellData(cRow, "BZ_PROCS_NO");
    arrPar[2] = dts_listPrelisting.getCellData(cRow, "COM_NM");
};

/**
 * @method
 * @name setParDtl
 * @description set Par Dtl 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParDtl = async function(arrPar) {
    await scwin.listSync();
};

/**
 * @method
 * @name openDtl
 * @description open Dtl 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDtl = async function(row) {
    if ((row <= dts_listPrelisting.getRowCount()) && (dts_listPrelisting.getRowCount() > 0)) {
        scwin.fn_GetPar = scwin.getParDtl;
        fn_SetPar = scwin.setParDtl;

        // frame.CreateFrame("DLG_PRECOM_DTL","../lstproc/ULDSTF05004.gfm", "예비심사청구상세", 10, 10, 1055 + 5, 670 + 30, "window", 0, 0, false);
        if ($c.frame.path("/top") !== undefined) {
            $c.frame.path("/top").WinOpen("DLG_PRECOM_DTL", "../lstproc/ULDSTF05004.gfm?" + frame.FrameID, "예비심사청구상세", 1055 + 5, 700 + 30);
        } else {
            await $c.frame.CreateFrame("DLG_PRECOM_DTL", "../lstproc/ULDSTF05004.gfm", "예비심사청구상세", 10, 10, 1055 + 5, 700 + 30, "window", 0, 0, false);
        }
    }
};

/**
 * @method
 * @name openInvRst
 * @description open Inv Rst 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInvRst = async function(row) {
    if ((row <= dts_listPrelisting.getRowCount()) && (dts_listPrelisting.getRowCount() > 0)) {
        scwin.fn_GetPar = scwin.getParDtl;
        fn_SetPar = undefined;
        const options = {
            id: "ULDSTF05010",
            title: "위원회결과",
            type: "browserPopup",
            width: 545 + 5,
            height: 600 + 30,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../lstproc/ULDSTF05010.gfm", options);
    }
};

/**
 * @method
 * @name openPubofr
 * @description open Pubofr 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPubofr = async function(row) {
    if ((row <= dts_listPrelisting.getRowCount()) && (dts_listPrelisting.getRowCount() > 0)) {
        scwin.fn_GetPar = scwin.getParDtl;
        fn_SetPar = undefined;
        if ($c.frame.path("/top") !== undefined) {
            $c.frame.path("/top").WinOpen("DLG_PRECOM_DTL", "../lstproc/ULDSTF05009.gfm?" + frame.FrameID, "공모", 795 + 5, 660 + 30);
        } else {
            await $c.frame.CreateFrame("DLG_PRECOM_DTL", "../lstproc/ULDSTF05009.gfm", "공모", 10, 10, 795 + 5, 660 + 30, "window", 0, 0, false);
        }
    }
};
